'use client';

import { IconCheck } from '@tabler/icons-react';
import { useMemo, type HTMLAttributes, type JSX, type ReactNode } from 'react';
import { Button as RACButton, useLocale } from 'react-aria-components';
import styles from './steps.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

export interface StepItem {
  id: string;
  label: ReactNode;
  description?: ReactNode;
}

export type StepStatus = 'complete' | 'current' | 'upcoming';

export interface StepsProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  steps: StepItem[];
  /** Id of the current step. Steps before it are complete, steps after it are upcoming. */
  current: string;
  orientation?: 'horizontal' | 'vertical';
  /** Makes completed steps buttons that navigate back to them. */
  onStepPress?: (id: string) => void;
  /** Accessible name of the list. */
  'aria-label'?: string;
  /** Read after a completed step's label by screen readers ("Details, completed"). */
  completedLabel?: string;
  /** Words used in the narrow summary "Step 2 of 3". */
  stepLabel?: string;
  ofLabel?: string;
}

/**
 * Progress through a multi-step flow. Renders an ordered list with `aria-current="step"` on the current step.
 * Horizontal steps collapse to "Step 2 of 3 · Upload" plus a segmented bar when their container is too narrow
 * (under 480px for up to 3 steps, 640px for more).
 */
export function Steps({
  steps,
  current,
  orientation = 'horizontal',
  onStepPress,
  'aria-label': ariaLabel = 'Progress',
  completedLabel = 'completed',
  stepLabel = 'Step',
  ofLabel = 'of',
  className,
  ...rest
}: StepsProps): JSX.Element {
  const { locale } = useLocale();
  const nf = useMemo(() => new Intl.NumberFormat(locale), [locale]);
  const currentIndex = Math.max(0, steps.findIndex((s) => s.id === current));
  const status = (i: number): StepStatus => (i < currentIndex ? 'complete' : i === currentIndex ? 'current' : 'upcoming');
  const currentStep = steps[currentIndex];

  return (
    <div
      {...rest}
      className={cx(styles.root, className)}
      data-orientation={orientation}
      data-size={steps.length <= 3 ? 'sm' : 'lg'}
    >
      <ol className={styles.list} aria-label={ariaLabel}>
        {steps.map((step, i) => {
          const s = status(i);
          const body = (
            <>
              <span className={styles.marker} aria-hidden="true">
                {s === 'complete' ? <IconCheck size="1.15em" stroke={2.25} /> : nf.format(i + 1)}
              </span>
              <span className={styles.label}>
                {step.label}
                {s === 'complete' && <span className={styles.srOnly}>, {completedLabel}</span>}
              </span>
              {step.description != null && <span className={styles.description}>{step.description}</span>}
            </>
          );
          return (
            <li key={step.id} className={styles.step} data-status={s} aria-current={s === 'current' ? 'step' : undefined}>
              {s === 'complete' && onStepPress ? (
                <RACButton className={cx(styles.body, styles.button)} onPress={() => onStepPress(step.id)}>
                  {body}
                </RACButton>
              ) : (
                <div className={styles.body}>{body}</div>
              )}
              {i < steps.length - 1 && <span className={styles.connector} aria-hidden="true" />}
            </li>
          );
        })}
      </ol>

      {orientation === 'horizontal' && currentStep && (
        <div className={styles.compact}>
          <p className={styles.summary}>
            <span className={styles.summaryCount}>
              {stepLabel} {nf.format(currentIndex + 1)} {ofLabel} {nf.format(steps.length)}
            </span>
            <span className={styles.summaryDot} aria-hidden="true">
              ·
            </span>
            <span className={styles.summaryLabel}>{currentStep.label}</span>
          </p>
          <span className={styles.segments} aria-hidden="true">
            {steps.map((step, i) => (
              <span key={step.id} className={styles.segment} data-status={status(i)} />
            ))}
          </span>
        </div>
      )}
    </div>
  );
}

/*
 * Steps — numbered markers joined by connectors. Marker size follows density (control height − 8px).
 * --_marker is a private alias for that size, not a theme token.
 */

.root {
  --_marker: calc(var(--strata-control-height) - var(--strata-space-2));

  box-sizing: border-box;
  container: strata-steps / inline-size;
  inline-size: 100%;
  min-inline-size: 0;
}

.list {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
}

.srOnly {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ------------------------------------------------------------------ *
 * Step body: marker + label (+ description)
 * ------------------------------------------------------------------ */

.body {
  box-sizing: border-box;
  display: grid;
  grid-template-columns: var(--_marker) minmax(0, auto);
  grid-template-rows: var(--_marker) auto;
  grid-template-areas:
    'marker label'
    '. description';
  column-gap: var(--strata-space-2);
  align-items: center;
  min-inline-size: 0;
  text-align: start;
}

.button {
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--strata-radius-badge);
  background-color: transparent;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  cursor: pointer;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}

.button[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}

.button[data-hovered] .label {
  text-decoration-line: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

.marker {
  box-sizing: border-box;
  grid-area: marker;
  display: inline-grid;
  place-items: center;
  inline-size: var(--_marker);
  block-size: var(--_marker);
  border: 1px solid var(--strata-color-border-strong);
  border-radius: var(--strata-radius-pill);
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  font-variant-numeric: tabular-nums;
  font-weight: var(--strata-font-weight-medium);
  line-height: 1;
}

.label {
  grid-area: label;
  min-inline-size: 0;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-snug);
}

.description {
  grid-area: description;
  min-inline-size: 0;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-xs);
  line-height: var(--strata-line-height-snug);
}

.step[data-status='complete'] .marker {
  border-color: var(--strata-color-action-primary-bg);
  background-color: var(--strata-color-action-primary-bg);
  color: var(--strata-color-action-primary-fg);
}

.step[data-status='current'] .marker {
  border: 2px solid var(--strata-color-action-primary-bg);
  color: var(--strata-color-text-default);
  font-weight: var(--strata-font-weight-semibold);
}

.step:is([data-status='complete'], [data-status='current']) .label {
  color: var(--strata-color-text-default);
}

.connector {
  display: block;
  border-radius: var(--strata-radius-pill);
  background-color: var(--strata-color-border-default);
}

.step[data-status='complete'] > .connector {
  background-color: var(--strata-color-action-primary-bg);
}

/* ------------------------------------------------------------------ *
 * Horizontal
 * ------------------------------------------------------------------ */

.root[data-orientation='horizontal'] .list {
  align-items: flex-start;
  gap: var(--strata-space-3);
}

.root[data-orientation='horizontal'] .step {
  display: flex;
  flex: 1 1 0;
  align-items: flex-start;
  gap: var(--strata-space-3);
  min-inline-size: 0;
}

.root[data-orientation='horizontal'] .step:last-child {
  flex: 0 1 auto;
}

.root[data-orientation='horizontal'] .body {
  flex: 0 1 auto;
}

.root[data-orientation='horizontal'] .connector {
  flex: 1 1 var(--strata-space-6);
  min-inline-size: var(--strata-space-4);
  block-size: 2px;
  /* Centred on the marker. */
  margin-block-start: calc(var(--_marker) / 2 - 1px);
}

/* ------------------------------------------------------------------ *
 * Vertical
 * ------------------------------------------------------------------ */

.root[data-orientation='vertical'] .list {
  flex-direction: column;
}

.root[data-orientation='vertical'] .step {
  position: relative;
  padding-block-end: var(--strata-space-6);
}

.root[data-orientation='vertical'] .step:last-child {
  padding-block-end: 0;
}

.root[data-orientation='vertical'] .connector {
  position: absolute;
  inset-block: calc(var(--_marker) + var(--strata-space-1)) var(--strata-space-1);
  inset-inline-start: calc(var(--_marker) / 2 - 1px);
  inline-size: 2px;
}

.root[data-orientation='vertical'] .description {
  margin-block-start: calc(var(--strata-space-1) * -1);
}

/* ------------------------------------------------------------------ *
 * Narrow: "Step 2 of 3 · Upload" + segmented bar
 * ------------------------------------------------------------------ */

.compact {
  display: none;
  gap: var(--strata-space-2);
}

.summary {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: var(--strata-space-2);
  margin: 0;
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-snug);
}

.summaryCount {
  color: var(--strata-color-text-subtle);
  font-variant-numeric: tabular-nums;
}

.summaryDot {
  color: var(--strata-color-text-subtle);
}

.summaryLabel {
  min-inline-size: 0;
  color: var(--strata-color-text-default);
  font-weight: var(--strata-font-weight-medium);
}

.segments {
  display: flex;
  gap: var(--strata-space-1);
}

.segment {
  flex: 1 1 0;
  block-size: var(--strata-space-1);
  border-radius: var(--strata-radius-pill);
  background-color: var(--strata-color-border-default);
}

.segment:is([data-status='complete'], [data-status='current']) {
  background-color: var(--strata-color-action-primary-bg);
}

@container strata-steps (inline-size < 480px) {
  .root[data-orientation='horizontal'] .list {
    display: none;
  }

  .root[data-orientation='horizontal'] .compact {
    display: grid;
  }
}

@container strata-steps (480px <= inline-size < 640px) {
  .root[data-orientation='horizontal'][data-size='lg'] .list {
    display: none;
  }

  .root[data-orientation='horizontal'][data-size='lg'] .compact {
    display: grid;
  }
}
